#pragma once
#include "core.hpp"
#include <cstdint>
struct DllDeclaration{bool found=false;uint32_t flags=0,extra=0,minSkse=0,timestamp=0;vector<uint32_t>runtimes;};
inline uint32_t pe32(const string&s,size_t p){if(p>s.size()||s.size()-p<4)throw std::runtime_error("DLL truncada");return (uint32_t)(unsigned char)s[p]|((uint32_t)(unsigned char)s[p+1]<<8)|((uint32_t)(unsigned char)s[p+2]<<16)|((uint32_t)(unsigned char)s[p+3]<<24);}
inline unsigned pe16(const string&s,size_t p){if(p>s.size()||s.size()-p<2)throw std::runtime_error("DLL truncada");return (unsigned char)s[p]|((unsigned char)s[p+1]<<8);}
inline DllDeclaration dllDeclaration(const string&s){
 DllDeclaration d;if(s.size()<64||s.substr(0,2)!="MZ")throw std::runtime_error("Arquivo sem cabecalho PE");size_t pe=pe32(s,60);if(pe>s.size()||s.size()-pe<24||s.compare(pe,4,string("PE\0\0",4)))throw std::runtime_error("Cabecalho PE invalido");if(pe16(s,pe+4)!=0x8664)throw std::runtime_error("DLL nao e Windows x64");unsigned count=pe16(s,pe+6),optional=pe16(s,pe+20);if(count>96||optional<120||pe+24+optional>s.size())throw std::runtime_error("Tabela PE invalida");size_t opt=pe+24;if(pe16(s,opt)!=0x20b)throw std::runtime_error("Formato PE64 esperado");if(pe32(s,opt+108)==0)return d;uint32_t exp=pe32(s,opt+112),expSize=pe32(s,opt+116);if(!exp)return d;
 auto offset=[&](uint32_t rva,size_t bytes)->size_t{size_t sections=opt+optional;for(unsigned i=0;i<count;i++){size_t p=sections+i*40;if(p+40>s.size())throw std::runtime_error("Secao PE truncada");uint32_t start=pe32(s,p+12),raw=pe32(s,p+16),at=pe32(s,p+20);if(rva>=start&&(uint64_t)rva-start+bytes<=raw){uint64_t file=(uint64_t)at+rva-start;if(file+bytes>s.size())throw std::runtime_error("Dados da DLL truncados");return (size_t)file;}}throw std::runtime_error("Endereco PE fora das secoes");};
 size_t e=offset(exp,40);unsigned n=pe32(s,e+24),functions=pe32(s,e+20);if(n>65536||functions>65536)throw std::runtime_error("Tabela de exportacoes grande demais");size_t names=offset(pe32(s,e+32),(size_t)n*4),ordinals=offset(pe32(s,e+36),(size_t)n*2),funcs=offset(pe32(s,e+28),(size_t)functions*4);
 for(unsigned i=0;i<n;i++){auto rva=pe32(s,names+i*4);string name;for(size_t j=0;j<128;j++){char c=s[offset(rva+j,1)];if(!c)break;name+=c;}if(name!="SKSEPlugin_Version")continue;auto ordinal=pe16(s,ordinals+i*2);if(ordinal>=functions)throw std::runtime_error("Ordinal PE invalido");auto address=pe32(s,funcs+ordinal*4);if(address>=exp&&(uint64_t)address<((uint64_t)exp+expSize))return d;size_t p=offset(address,848);if(pe32(s,p)!=1)throw std::runtime_error("Declaracao SKSE de versao nao suportada");d.found=true;d.extra=pe32(s,p+772);d.flags=pe32(s,p+776);d.minSkse=pe32(s,p+844);d.timestamp=pe32(s,pe+8);for(int j=0;j<16;j++){auto v=pe32(s,p+780+j*4);if(!v)break;d.runtimes.push_back(v);}return d;}return d;
}
inline uint32_t packedRuntime(string s){vector<unsigned long>v;std::stringstream ss(s);string token;try{while(std::getline(ss,token,'.')){if(token.empty()||token.find_first_not_of("0123456789")!=string::npos)return 0;v.push_back(std::stoul(token));}}catch(...){return 0;}if(v.size()<3||v.size()>4||v[0]>255||v[1]>255||v[2]>4095||(v.size()==4&&v[3]>15))return 0;return (v[0]<<24)|(v[1]<<16)|(v[2]<<4)|(v.size()==4?v[3]:0);}
inline string runtimeText(uint32_t v){return std::to_string(v>>24)+"."+std::to_string((v>>16)&255)+"."+std::to_string((v>>4)&4095);}
struct DllVerdict{bool blocked=false,requiresAddress=false;string status,reason;};
inline DllVerdict evaluateDll(const DllDeclaration&d,uint32_t runtime){
 DllVerdict v{false,false,"NAO VERIFICADO","DLL sem declaracao SKSE legivel. Confira o log e a pagina do autor."};if(!d.found)return v;v.requiresAddress=(d.flags&1)!=0;
 if(!runtime||runtime<packedRuntime("1.6.318")||runtime>packedRuntime("1.7.104")){v.reason="Runtime fora do intervalo de regras locais. Declaracao extraida, mas sem conclusao automatica.";return v;}
 if((d.flags&~7u)||(d.extra&~3u)){v.reason="A DLL usa flags desconhecidas; confira suporte na pagina do autor.";return v;}
 bool independent=(d.flags&3)!=0;string reason="A lista declarada na DLL nao inclui o runtime "+runtimeText(runtime)+".";
 if((d.flags&1)&&runtime>=packedRuntime("1.7.99")&&!(d.extra&2)&&d.timestamp>=520128000&&d.timestamp<1748217600){independent=false;reason="DLL antiga para o formato novo da Address Library. Precisa de uma compilacao compativel com este runtime; atualizar somente a Address Library nao recompila a DLL.";}
 if(independent&&runtime<packedRuntime("1.6.629")&&(d.flags&4)&&!(d.extra&1)){v.blocked=true;v.status="INCOMPATIBILIDADE DECLARADA";v.reason="DLL declara estruturas a partir de 1.6.629. Para este jogo, procure a variante antiga do MOD compativel com "+runtimeText(runtime)+".";return v;}
 if(independent&&runtime>=packedRuntime("1.6.629")&&!(d.flags&4)&&!(d.extra&1)){v.blocked=true;v.status="INCOMPATIBILIDADE DECLARADA";v.reason="DLL declara estruturas anteriores a 1.6.629. Instale a variante para "+runtimeText(runtime)+".";return v;}
 if(!independent&&std::find(d.runtimes.begin(),d.runtimes.end(),runtime)==d.runtimes.end()){v.blocked=true;v.status="INCOMPATIBILIDADE DECLARADA";v.reason=reason;return v;}
 v.status="DECLARACAO SEM BLOQUEIO";v.reason="As regras locais nao encontraram bloqueio de runtime nesta declaracao. Isso nao testa carregamento, requisitos externos ou estabilidade.";return v;
}
inline DllDeclaration inspectDll(const fs::path&p){std::error_code ec;auto size=fs::file_size(nativePath(p),ec);if(ec||size>64*1024*1024)throw std::runtime_error("DLL inacessivel ou maior que 64 MiB");return dllDeclaration(readFile(nativePath(p)));}
